var r=[{title:`Bänkar för stöd och press`,text:`En platt bänk stöder pressar, rodd och sittande rörelser. En justerbar bänk ändrar din överkroppsvinkel för pressar och andra övningar. Kontrollera att dess angivna kapacitet täcker dig plus eventuell extra vikt, lås inställningen och se till att den inte gungar eller glider innan du lastar den. En stol är inte automatiskt en säker viktbänk.`},{title:`Ett stabilt steg`,text:`Uppsteg, armhävningar med upphöjda händer och lågintensiv stegträning kräver en plattform som inte välter. Börja med ett lågt steg som låter höft och knä röra sig med kontroll. Sätt hela stödfoten på steget, kliv ner medvetet och tryck inte ifrån med den bakre foten för att dölja en plattform som är för hög.`},{title:`Anpassa ett hopprep`,text:`Som en grov första kontroll, stå med en fot på mitten av repet och lyft handtagen. Många hopprep för fritidsbruk passar när handtagen når ungefär nedre bröstet eller armhålorna, även om repets utformning och färdighet påverkar den ideala längden. Ett rep som är för kort träffar dina fötter. Ett som är för långt fastnar i marken och kan leda till stora armcirklar.`},{title:`Kontrollera utrymmet och utrustningen`,text:`Använd ett halkfritt golv och se upp för möbler, lampor, fläktar och andra personer. Hopprep kräver plats ovanför och åt sidorna såväl som golvyta. Före varje pass, kontrollera om repets beläggning är sliten, om det finns vassa trådändar, skadade bänkgångjärn och lösa stegytor. Byt ut trasig utrustning i stället för att improvisera reparationer.`},{title:`Så använder du TrainUp`,text:`Ange din bänktyp, golvyta, takhöjd, underlag och om hopp är okej i Profil, så väljer programmet bara övningar som passar dem. Om dina knän eller ditt utrymme utesluter ett steg, eller buller, stötar eller takhöjd utesluter repet, är övningar utan steg och stillastående marsch alternativen.`}];var n=[{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: säkerhet och teknik vid styrketräning`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};